 return source.filter(point=>Array.isArray(point)&&typeof point[0]==='string'&&Number.isFinite(+point[1])).map(([day,value])=>{const delta=+value-prev;prev=+value;return [day,delta]}).filter(([day])=>inRange(day)).map(([day,delta])=>[day,rebased+=delta]);
