 const W=960,H=280,L=65,R=19,T=17,B=32,pw=W-L-R,ph=H-T-B;let lo=Math.min(...all),hi=Math.max(...all);if(unit==='rupees'){lo=Math.min(lo,0);hi=Math.max(hi,0)}const pad=(hi-lo||Math.abs(hi)*.05||1)*.12;lo-=pad;hi+=pad;
 const dateIndex=new Map(allDates.map((d,i)=>[d,i])); const x=d=>L+(dateIndex.get(d)/(allDates.length-1||1))*pw,y=v=>T+(hi-v)/(hi-lo)*ph;
