 charts={};
 const tradingTools=tools();
 const navigation=[
  ['TRADING DESK',[['terminal','activity','Trading terminal'],['orders','book','Orders'],['strategies','layers','Automatic strategies'],['desk','shield','Risk & alerts']]],
  ['RESEARCH',[['overview','chart','Performance'],['compare','layers','Compare algorithms'],['options','grid','Options lab'],['market','activity','Market data'],['journal','book','Backtest trades'],['review','file','Trade review']]],
  ['WORKSPACE',[['paper','wallet','Paper account'],['mobile','grid','Connect devices'],['sources','folder','Data & reports']]]
 ];
 const pageNames={desk:'Risk & alerts',options:'Options lab',review:'Trade review',strategies:'Automatic strategies',terminal:'Trading terminal',orders:'Orders',overview:'Performance',compare:'Compare algorithms',market:'Market data',journal:'Backtest trades',paper:'Paper account',sources:'Data & reports',mobile:'Connect devices'};
 const pages={desk:riskPage,options:optionsPage,review:reviewPage,strategies:workshopPage,terminal:terminalPage,orders:ordersPage,overview,compare,market:marketPage,journal,paper,sources,mobile};
